      "structure": "教皇编号Ⅴ，面向两位聆听者，知识在人物之间被公开传递。与女祭司未展开的信息相比，教皇偏向共同语言、传统与可学习的方法。它既可表示进入已有体系，也可引出体系是否仍适用的问题；并不意味着一个老师、机构或旧规定永远正确。",
