          "text": "若为了认可或短期回报作出自己难以接受的选择，逆位可表示价值与行动脱节。先确认违背的是核心需要还是可协商偏好，再考虑调整。不是所有不舒服都说明选择错误，真正要看愿不愿承担这种取舍。"
