        "study": {
          "upright": "学习时可关注课程与真正想学会的能力是否相符。选择专业、老师或练习方向，不只比较知名度，也看日常过程是否愿意投入。兴趣能够成为连接的起点，持续选择仍需考虑时间和精力，不能仅靠一时被吸引。",
          "reversed": "若只是为别人认可而选课，或在不同方向间不断摇摆而没有练习，逆位可帮助看见缺乏认同或回避取舍。把最重视的学习目标明确下来，再比较课程内容，比同时报很多课保留所有可能更容易形成持续行动。"
        },
        "life": {
          "upright": "生活里可对应与人建立真诚连接，也可对应个人在重要岔路上的选择。它鼓励让外在行动回应内心认同，而不是只照最省冲突的路走。决定需要面对现实条件，价值判断可以清楚，具体实现方式仍可逐步调整。",
          "reversed": "若一直说随便、都行，最后却因选择不合意而积累不满，逆位可提醒自己的需要没有进入决定。也可能每次都把选择交给别人。清楚说明偏好和底线，参与讨论，比事后用不被理解解释全部问题更有用。"
        }
