          "upright": "关系里可表示需要独处、慢一点理解感受，或希望有更深的交流。保留个人空间不等于拒绝亲密，关键是能否说明需要和联系安排。它适合观察双方怎样容纳各自的内在生活，不应直接读成对方已经不爱或永远独身。",
          "reversed": "若以需要空间回避所有回应，关系可能失去必要交流；若因害怕失去而不给彼此安静，也会难以辨认真实需要。逆位帮助检查独处与联系的比例。具体行为和已说明的约定，比猜测沉默背后的心理事实更可靠。"
