      "structure": "倒吊人编号Ⅻ，人物倒悬，却有平静表情与头部光环。它呈现暂停惯常推进、暂时让出控制的状态，以便改变视角。悬停不同于阶段结束：事情可能仍在，但看待方式和行动节奏需要改变。它不要求忍受一切，也不把所有付出都称为有意义的牺牲。",
