        "money": {
          "upright": "资源安排可关注支出类别、固定需要与可调整部分的比例。计划应能照顾日常生活又支持目标，不以极端节省制造难以持续的压力。定期按真实收支微调，比把某个比例奉为适用于所有人的答案更贴近节制。",
          "reversed": "若一段过度花费后用极端压缩补偿，或预算各部分相互挤占，可检查调整是否可持续。先明确不可省的基本需要与能变动的费用，再作适度修正。此牌不提供投资配比建议，比例必须依据真实条件而非图像决定。"
        },
        "study": {
          "upright": "学习中适合安排能持续的练习和休息，让阅读、回忆与应用互相配合。理解需要时间，短而稳定的循环可能比偶尔猛烈投入更有帮助。节制并不规定每天学一半、休息一半，而是让投入与精力反馈相配。",
          "reversed": "熬夜猛学后几天不碰，或只读不练、只做题不回看，可表现为节奏与方法失衡。先调整一个具体环节，观察能否持续，再继续修改。追求瞬间完美计划反而可能增加负担，真正协调需要经过几轮实际尝试。"
        },
        "life": {
          "upright": "生活里可对应饮食、作息、工作与个人时间的相互配合。它不是把所有事平均分，而是看不同需要在当前阶段怎样共存。小幅调整时间和环境，留意身体与生活反馈，能让习惯逐渐形成，不必靠突然改变全部生活证明决心。",
          "reversed": "若生活常靠极端补偿维持，如忙到完全忽略自己再一次放纵，可检查安排是否缺少连续性。逆位提醒的是配比问题，不给健康作诊断。选择一个容易保持的小变化，比反复制定一次性彻底改变的计划更有实际依据。"
        }
