      "structure": "月亮编号ⅩⅧ，月光、犬狼、从水中出现的甲壳动物与通向远方的路构成未知环境。它突出模糊、想象、感受与不安怎样相互影响。与女祭司安静容纳未明信息相比，月亮更容易使空白变得情绪强烈；梦和直觉可以被聆听，但不是外部事实的替代品。",
