          "reversed": "感情逆位可能是有好感但不敢表达，也可能是努力营造开心气氛，却忽略了真实的不舒服。先分清快乐难以感受，还是关系确实缺少回应。对方未必能从沉默中猜出期待，需要用明确、不过度施压的话沟通。若总由一人负责维持阳光形象，也应允许失望和分歧被看见，而不把它们当作关系失败。"
