          "reversed": "预算只写最终规模，没安排过渡费用，可能是远景脱离当前资源；过度担心每种不确定，又可能让必要选择一直搁置。先找出可验证的约束与自己的承受范围，避免把犹豫包装成永久等待最佳机会。"
