          "id": "c09",
          "text": "圣杯九偏向自己感到满足，权杖六偏向成果受到外界认可。一个人可能很满意作品却未被看见，也可能得到赞赏却没有满足感。两者同时出现时，才可以分别讨论内在感受与外部评价是否一致。"
