          "title": "具体的肯定",
          "situation": "学生第一次完整讲清一个复杂题目，同学夸赞推理过程清楚，他却只说是运气。",
          "reading": "权杖六可提醒接受这份具体反馈：这次进展与步骤组织和表达有关，值得保留。认可不证明以后每题都对，却能指出已经形成的能力；将功劳完全推给运气，反而错失可复用的方法。"
