          "situation": "主持读书会的人喜欢热闹讨论，但有成员更愿意先写几句话再发言。",
          "reading": "权杖王后的带动可以是创造多种参与方式，而非要求大家都像自己一样外向。给安静成员留位置，既保留活力，也让自信不靠主导每一刻维持。共同参与比单一气氛更能体现成熟感染力。"
