        "money": {
          "upright": "共同资源安排需要相互理解和明确约定，可以是分担费用、协商报酬或讨论使用权限。平等不要求每次数字相同，而是相关人都了解并愿意接受安排。亲近不能代替清楚账目，也不保证财务合作顺利。",
          "reversed": "可能不好意思谈费用，导致一方默认承担；也可能用金钱换取并未说清的情感回应。先区分赠与、借用和共同支出，再确认双方期待。此牌关注交换关系，不作借贷、投资或收益保证。"
        },
        "study": {
          "upright": "同伴互讲、互相检查思路，可以让理解通过回应深化。好的学习伙伴不仅给答案，也愿意听清彼此怎样推理。遇到不懂时能说明，懂了时能回应，这种交换比两个人只是坐在一起更接近共同学习。",
          "reversed": "可能一人总讲、一人被动听，或为了不伤关系而不指出误解。建立轮流解释与核对的方式，能让双方都有参与位置。意见不同并不破坏学习伙伴关系，无法表达差异才会限制互相帮助。"
        },
        "life": {
          "upright": "可以认真经营一对一连接，愿意听别人，也让自己的需要被听见。一次平等而具体的对话，就能形成互相承认的经验。此牌不要求每段友谊都亲密无间，适合的距离也能支持可靠联系。",
          "reversed": "若总猜测别人希望什么而不说自己需要，关系可能表面和谐、实际单向。也可能暂时不想靠近但难以说明。清楚表达能够做什么、不能做什么，有助于让连接建立在真实选择而非默认义务上。"
        }
