          "reversed": "可能双方对幸福生活的想象不同，或为了外表和谐压住不满。先讨论作息、分工、私人空间和未来期待，比追求统一的浪漫画面更有帮助。共同生活应容纳真实的人，而非让人只扮演理想角色。"
