          "title": "结束的是方法",
          "situation": "小林连续数周用熬夜补任务，终于发现这种方式已无法维持，决定重谈范围和交接。",
          "reading": "宝剑十可指熬夜硬撑的办法到头，不必等于失去工作。承认范围，才能具体停止消耗；若只休一天再照旧，终点尚未被真正接受。"
