          "upright": "可能以试探、提问或观察来接近关系，对细节很敏感。需要让沟通逐渐直接，而非永远靠旁敲侧击。它不证明对方监视或不信任，也不读取心思；可看真实交流是否增加，问题是否允许彼此解释而非成为审问。",
          "reversed": "误会可能来自猜消息、截图缺语境或为了防受伤反复试探。先核对事实和双方约定，少用猜测填补。若自己不敢问，选择一条可具体回应的问题；若问题带攻击性，则需恢复理解目的，不能把亲近变成持续的证据搜集。"
