          "reversed": "可能被零散信息带走，或在会议中急于显得懂而反驳。明确要核实的问题，保留来源与限制。若组织不允许提问，也需看环境怎样压住学习，不能把不敢表达全部归于个人；有价值的疑问应有被回应的渠道。"
