          "reversed": "容易被紧迫感牵动，来不及理解条件就决定，或为证明自己判断正确继续加码。先限定可承受范围并回看事实。它不提供抢先获利的暗示；停止一项未经理解的行动，比害怕错过而继续冲更能保留选择。"
