          "reversed": "可能没读完题就答、用熟悉套路套陌生条件，或急于反驳老师而没听清内容。先慢下关键一步，再恢复速度。若精力分散，不必同时攻全部难点；选择一项可检验的任务，能让行动重新有方向。"
