        "career": {
          "upright": "适合审稿、核对需求、提出问题与澄清责任。专业判断可以很明确，但应让同事看见依据与修正路径。面对含糊承诺，追问交付标准和截止时间；面对不同意见，区分信息缺失与价值分歧，避免把质疑方案理解成否定个人。",
          "reversed": "团队中可能出现言辞刻薄、用经验压人或对反馈过度防御。如果批评准确却无人知道如何改进，信息仍没有完成传递。也要检查自己是否担心破坏关系而不指出真实风险；把问题落在材料、流程和具体责任上，有助于恢复合作。"
        },
        "money": {
          "upright": "关注条款、费用和个人资源边界。面对借款或共同支出，可以直接问清偿还安排、自己的承受范围及退出条件，拒绝含糊承诺并不等于不近人情。清楚记录比依靠熟人关系猜测更可靠，尤其不要因不好意思而跳过必要核对。",
          "reversed": "若金钱分歧演变成道德指责，先恢复账目和约定的可核查性。有时过往损失让人对所有合作一概防备，有时又因怕被说计较而接受不合理要求。需要识别实际条件，把风险、关系和情绪分开，不在激愤中作出资源承诺。"
        },
        "study": {
          "upright": "学习时适合辨别论证、校正概念和删去没有依据的结论。能指出哪里不成立，也应说明缺少什么证据、怎样改写更准确。讨论中允许自己修正观点；真正的独立思考来自理解理由，而不是总与多数人持不同意见。",
          "reversed": "留意把批判当成否定一切，或因为怕答错而不表达尚在形成的想法。若笔记全是别人哪里有问题，却没有自己的论证，可试着补上一个可检验的主张。若反馈过于刺耳，先提取能帮助修改的内容，再判断表达方式是否需要回应。"
        },
        "life": {
          "upright": "日常生活中适合整理人际和事务边界，把不舒服的含糊局面说清楚。减少过度解释，也不必靠疏远表达拒绝。面对信息嘈杂的环境，保留核实和独处的空间，让自己能在情绪之后作出判断，而不被每次外界反应牵着走。",
          "reversed": "当清醒变成持续挑剔，周围可能只剩错误而没有可亲近之处。也可能一直替别人找理由，忽略自己的疲惫。辨别的目标是形成可生活的选择，不是把自己训练成没有需要的人；合适的支持与清楚的界限并不冲突。"
        }
