          "reversed": "有好感却没有时间、生活安排不兼容，或承诺始终不落地，都可能是逆位所提示的条件问题。先确认障碍能否解决，而不是单凭热情填补。若只追求理想开局而拒绝普通相处，也需给真实了解留下逐步展开的机会。"
