          "reversed": "若一方总被临时取消、联系取决于另一方有空，协调可能已变成单方面等待。也可能双方承诺超出容量，容易把疲惫误读为态度问题。先核对时间与优先级，减少无法兑现的安排，再看关系中是否存在长期不公平的分配。"
