      "structure": "星币三把个人技艺放进共同完成的工作里。工匠在建筑内部作业，另外两人带着图纸参与讨论；作品要能承接不同人的知识与需要。三的主题是让能力、沟通和标准形成配合，不只是热闹地聚在一起。它既可描述专业技能被看见，也可描述人愿意接受具体反馈，让自己的部分成为整体中真正可用的一环。",
