          "reversed": "若费用无人核对、责任互相推诿，或有人凭专业身份拒绝解释账目，逆位提示协作并不透明。把支出依据、批准权限和记录方式说清楚。也要避免每个人只管自己的部分，却没人确认总额与整体目标是否相容。"
