          "title": "有边界的共享",
          "situation": "室友想借相机，小方担心损坏，原本准备直接拒绝，后来决定说明使用范围和归还安排。",
          "reading": "星币四可以读成保护真实资源。清楚条件让双方知道责任，也让分享成为可选择的行动。关键不在是否必须借出，而是决定有依据，既不被不好意思推动，也不把所有请求自动当成威胁。"
