          "title": "让错误进入下一次",
          "situation": "小陆总把宝剑牌解释成冲突，做题后知道答案不同，却下次仍按相同关键词选择。",
          "reading": "星币八的关键是把反馈转成练习。可以选两张看似相近的牌，指出画面差异并分别解释，再做一个新情境。题量不必立即增加，先让一个错误真的改变下一次判断，才算有效打磨。"
