          "reversed": "若双方家庭规则冲突、共同资源分配不清，或一方必须牺牲选择才能维持体面，逆位提示长期结构需要调整。先把实际责任与期望说具体，避免用传统或归属要求一方沉默，也不把所有分歧都视为关系注定不合。"
