          "reversed": "若只研究怎样相处却不实际沟通，或因怕表现不好而迟迟没有回应，逆位提示行动受阻。另一种情况是兴趣很快转移、每次只停在新鲜开头。先看具体行为与可用时间，不把笨拙自动视为不认真，也不替反复失约找无限理由。"
