          "reversed": "若长期沿用不适合的安排，或因厌烦省略账目与费用核查，逆位提醒恢复实际观察。稳定不等于永远不变，改变也不必一次推翻全部。可以先核对一项持续成本或维护责任，依据事实调整，避免由习惯替代判断。"
