          "reversed": "若替别人承担费用已影响基本需要，或购买许多照顾用品却没有实际用途，逆位提示资源偏离容量。先核对责任与需求，保留自己的必要支持。拒绝超出能力的支出不等于冷漠，也不要以金钱投入要求对方交出所有决定权。"
